use gpui_mesh::{Association, DataSet, Field, FieldData};
use gpui_dataset_transformation::{point_data_to_cell_data,cell_data_to_point_data};
use gpui_profiler::AllocProbe;
use std::{hint::black_box,time::Instant};
fn validate(output:&DataSet, association:Association, expected:&[f64], vector:bool) {
    let field=output.field(association,"out").unwrap();
    assert!(field.valid.as_ref().is_none_or(|mask|mask.iter().all(|&valid|valid)));
    match &field.data {
        FieldData::Scalar(values)=>{
            assert!(!vector); assert_eq!(values.len(),expected.len());
            for (&a,&b) in values.iter().zip(expected) { assert!((a-b).abs()<1e-10); }
        }
        FieldData::Vector(values)=>{
            assert!(vector); assert_eq!(values.len(),expected.len());
            for (a,&b) in values.iter().zip(expected) {
                for (axis,factor) in [1.0,2.0,-0.5].into_iter().enumerate() { assert!((a[axis]-b*factor).abs()<1e-10); }
            }
        }
        _=>panic!("unexpected output"),
    }
}
fn measure(n:usize,label:&str, association:Association, expected:&[f64], vector:bool,mut operation:impl FnMut()->DataSet) {
    let warm=black_box(operation()); validate(&warm,association,expected,vector); drop(warm);
    let mut times=Vec::with_capacity(5); let mut counts=Vec::with_capacity(5); let mut bytes=Vec::with_capacity(5);
    for _ in 0..5 {
        let mut probe=AllocProbe::new();
        let start=Instant::now();
        let output=black_box(operation());
        let elapsed=start.elapsed().as_nanos();
        let allocations=probe.sample("conversion");
        times.push(elapsed); counts.push(allocations.count); bytes.push(allocations.bytes);
        validate(&output,association,expected,vector); drop(output);
    }
    println!(r#"{{"n":{n},"case":"{label}","allocator_instrumentation":{},"times_ns":{times:?},"allocation_calls":{counts:?},"allocated_bytes":{bytes:?}}}"#,cfg!(feature="allocations"));
}
fn measure_batch(n:usize,label:&str,expected_cells:&[f64],expected_points:&[f64],mut operation:impl FnMut()->[DataSet;4]) {
    let check=|outputs:&[DataSet;4]| {
        validate(&outputs[0],Association::Cell,expected_cells,false);
        validate(&outputs[1],Association::Cell,expected_cells,true);
        validate(&outputs[2],Association::Point,expected_points,false);
        validate(&outputs[3],Association::Point,expected_points,true);
    };
    let warm=black_box(operation());check(&warm);drop(warm);
    let mut times=Vec::with_capacity(5);let mut counts=Vec::with_capacity(5);let mut bytes=Vec::with_capacity(5);
    for _ in 0..5 {
        let mut probe=AllocProbe::new();let start=Instant::now();let output=black_box(operation());
        let elapsed=start.elapsed().as_nanos();let allocations=probe.sample("conversion-batch");
        times.push(elapsed);counts.push(allocations.count);bytes.push(allocations.bytes);check(&output);drop(output);
    }
    println!(r#"{{"n":{n},"case":"{label}","allocator_instrumentation":{},"times_ns":{times:?},"allocation_calls":{counts:?},"allocated_bytes":{bytes:?}}}"#,cfg!(feature="allocations"));
}

fn main() {
    for n in [16usize,32,48] {
        let dataset=DataSet::structured_grid("conversion",[n;3],[0.0;3],[1.0;3]).unwrap();
        let point_values:Vec<_>=dataset.positions.iter().map(|p|0.5+(p[0]+2.0*p[1]-0.5*p[2])*0.015625).collect();
        let cell_values:Vec<_>=(0..dataset.cell_count()).map(|i|0.5+(i%13) as f64*0.03125).collect();
        let expected_cells:Vec<_>=(0..dataset.cell_count()).map(|cell|{
            let nodes=dataset.cells.cell(cell).unwrap(); let a=dataset.positions[nodes[0] as usize];let b=dataset.positions[nodes[6] as usize];
            0.5+((a[0]+b[0])*0.5+(a[1]+b[1])-(a[2]+b[2])*0.25)*0.015625
        }).collect();
        let mut sums=vec![0.0;dataset.point_count()];let mut counts=vec![0usize;dataset.point_count()];
        for (cell,&value) in cell_values.iter().enumerate() {
            for &node in dataset.cells.cell(cell).unwrap() { sums[node as usize]+=value; counts[node as usize]+=1; }
        }
        let expected_points:Vec<_>=sums.iter().zip(&counts).map(|(&sum,&count)|sum/count as f64).collect();
        let point_vectors:Vec<_>=point_values.iter().map(|&v|[v,2.0*v,-0.5*v]).collect();
        let cell_vectors:Vec<_>=cell_values.iter().map(|&v|[v,2.0*v,-0.5*v]).collect();
        let dataset=dataset.with_field(Field::scalar("point-s",point_values)).with_field(Field::vector("point-v",point_vectors))
            .with_field(Field::scalar("cell-s",cell_values).on_cells()).with_field(Field::vector("cell-v",cell_vectors).on_cells());
        dataset.validate().unwrap();
        measure(n,"point_scalar",Association::Cell,&expected_cells,false,||point_data_to_cell_data(&dataset,"point-s","out").unwrap());
        measure(n,"point_vector",Association::Cell,&expected_cells,true,||point_data_to_cell_data(&dataset,"point-v","out").unwrap());
        measure(n,"cell_scalar",Association::Point,&expected_points,false,||cell_data_to_point_data(&dataset,"cell-s","out").unwrap());
        measure(n,"cell_vector",Association::Point,&expected_points,true,||cell_data_to_point_data(&dataset,"cell-v","out").unwrap());
        #[cfg(feature="retained")]
        {
            let checked=dataset.validated().unwrap();
            measure(n,"retained_point_scalar",Association::Cell,&expected_cells,false,||gpui_dataset_transformation::point_data_to_cell_data_validated(checked,"point-s","out").unwrap());
            measure(n,"retained_point_vector",Association::Cell,&expected_cells,true,||gpui_dataset_transformation::point_data_to_cell_data_validated(checked,"point-v","out").unwrap());
            measure(n,"retained_cell_scalar",Association::Point,&expected_points,false,||gpui_dataset_transformation::cell_data_to_point_data_validated(checked,"cell-s","out").unwrap());
            measure(n,"retained_cell_vector",Association::Point,&expected_points,true,||gpui_dataset_transformation::cell_data_to_point_data_validated(checked,"cell-v","out").unwrap());
            measure_batch(n,"batch_validate_once",&expected_cells,&expected_points,||{
                let checked=dataset.validated().unwrap();
                [gpui_dataset_transformation::point_data_to_cell_data_validated(checked,"point-s","out").unwrap(),
                 gpui_dataset_transformation::point_data_to_cell_data_validated(checked,"point-v","out").unwrap(),
                 gpui_dataset_transformation::cell_data_to_point_data_validated(checked,"cell-s","out").unwrap(),
                 gpui_dataset_transformation::cell_data_to_point_data_validated(checked,"cell-v","out").unwrap()]
            });
        }
        #[cfg(not(feature="retained"))]
        measure_batch(n,"batch_validate_once",&expected_cells,&expected_points,||{
            dataset.validate().unwrap();
            [point_data_to_cell_data(&dataset,"point-s","out").unwrap(),point_data_to_cell_data(&dataset,"point-v","out").unwrap(),
             cell_data_to_point_data(&dataset,"cell-s","out").unwrap(),cell_data_to_point_data(&dataset,"cell-v","out").unwrap()]
        });
    }
}
